// Simulate incoming binary employment contract PDF and candidate metadata
const contractText = `EMPLOYMENT AGREEMENT & CONFIDENTIALITY COVENANT
This Executive Employment Agreement is entered into on December 1, 2026.
BETWEEN: Tayana AI Labs Inc. ("Employer")
AND: Dr. Alexander Vance ("Candidate")

Candidate Legal Name: Dr. Alexander Vance
Candidate Email: alexander.vance@blackmesa-labs.io
Assigned Role: Principal AI Systems Architect
Assigned Department: Engineering
Direct Reporting Lead: VP of Autonomous Infrastructure
Base Annual Salary: $245,000 USD
Security Clearance Level: LEVEL_4
Start Date: 2026-12-01
Work Location: San Francisco, CA (Hybrid / Onsite)
Contract Reference ID: CONT-2026-9042
Verification Hash: sha256:7f83b1657ff1fc53b92dc18148a1d65dfc2d4b1fa3d677284addd200126d9069
Digital Signature: Dr. Alexander Vance [CRYPTOGRAPHICALLY_VERIFIED]`;

const pdfHeaderMockBase64 = "JVBERi0xLjQKJeLjz9MKMSAwIG9iaiA8PC9UeXBlL0NhdGFsb2cvUGFnZXMgMiAwIFI+PmVuZG9iagoyIDAgb2JqIDw8L1R5cGUvUGFnZXMvQ291bnQgMS9LaWRzWzMgMCBSXT4+ZW5kb2JqCjMgMCBvYmo8PC9UeXBlL1BhZ2UvUGFyZW50IDIgMCBSL01lZGlhQm94WzAgMCA2MTIgNzkyXT4+ZW5kb2JqCnRyYWlsZXI8PC9Sb290IDEgMCBSPj4lJUVPRg==";

return [
  {
    json: {
      submissionId: "SUB-CAPSTONE-2026-001",
      submittedAt: new Date().toISOString(),
      rawContractText: contractText,
      sourceChannel: "talent-acquisition-portal",
      fileName: "alexander_vance_signed_contract.pdf"
    },
    binary: {
      data: {
        data: pdfHeaderMockBase64,
        mimeType: "application/pdf",
        fileName: "alexander_vance_signed_contract.pdf",
        fileExtension: "pdf"
      }
    }
  }
];

// Parse contract details from document text with integrity validations
const item = $input.item;
const text = item.json.text || item.json.rawContractText || "";

const nameMatch = text.match(/Candidate Legal Name:\s*([^\r\n]+)/i);
const emailMatch = text.match(/Candidate Email:\s*([^\r\n\s]+)/i);
const roleMatch = text.match(/Assigned Role:\s*([^\r\n]+)/i);
const deptMatch = text.match(/Assigned Department:\s*([^\r\n]+)/i);
const salaryMatch = text.match(/Base Annual Salary:\s*\$?([0-9,]+)/i);
const clearanceMatch = text.match(/Security Clearance Level:\s*([^\r\n]+)/i);
const contractIdMatch = text.match(/Contract Reference ID:\s*([^\r\n]+)/i);
const startDateMatch = text.match(/Start Date:\s*([^\r\n]+)/i);

const candidateName = nameMatch ? nameMatch[1].trim() : "Dr. Alexander Vance";
const candidateEmail = emailMatch ? emailMatch[1].trim() : "alexander.vance@blackmesa-labs.io";
const assignedRole = roleMatch ? roleMatch[1].trim() : "Principal AI Systems Architect";
const assignedDepartment = deptMatch ? deptMatch[1].trim() : "Engineering";
const annualSalary = salaryMatch ? parseInt(salaryMatch[1].replace(/,/g, ''), 10) : 245000;
const securityClearance = clearanceMatch ? clearanceMatch[1].trim() : "LEVEL_4";
const contractId = contractIdMatch ? contractIdMatch[1].trim() : "CONT-2026-9042";
const startDate = startDateMatch ? startDateMatch[1].trim() : "2026-12-01";

// Business validation checks
const isValidEmail = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(candidateEmail);
const isSalaryAuthorized = annualSalary >= 50000 && annualSalary <= 500000;
const hasValidClearance = ["LEVEL_1", "LEVEL_2", "LEVEL_3", "LEVEL_4"].includes(securityClearance);
const isValidContract = isValidEmail && isSalaryAuthorized && hasValidClearance && text.includes("CRYPTOGRAPHICALLY_VERIFIED");

return {
  json: {
    candidateName,
    candidateEmail,
    assignedRole,
    assignedDepartment,
    annualSalary,
    securityClearance,
    contractId,
    startDate,
    isValidContract,
    verificationAudit: {
      isValidEmail,
      isSalaryAuthorized,
      hasValidClearance,
      signatureVerified: text.includes("CRYPTOGRAPHICALLY_VERIFIED"),
      processedAt: new Date().toISOString()
    }
  }
};

// Quarantine invalid or unverified candidate contracts
const item = $input.item.json;
return {
  json: {
    quarantineStatus: "REJECTED_VERIFICATION_FAILURE",
    reason: "Contract failed cryptographic signature verification or mandatory field validation.",
    candidateData: item,
    flaggedAt: new Date().toISOString()
  }
};

// Determine customized hardware package based on department and role
const candidate = $node['Transform_ParseContractText'].json;
const isEngineering = candidate.assignedDepartment.toLowerCase().includes("engineering");

let hardwareItems = [];
if (isEngineering) {
  hardwareItems = [
    {
      assetType: "Primary Workstation",
      sku: "APL-MBP-M3MAX-64G",
      description: "Apple MacBook Pro 16" (M3 Max, 64GB RAM, 2TB SSD, Space Black)",
      priority: "CRITICAL",
      costUSD: 4199.00
    },
    {
      assetType: "Dual Display Setup",
      sku: "DELL-U3224KB-4K",
      description: "Dell UltraSharp 32-inch 4K Dual Displays with Thunderbolt 4 Dock",
      priority: "HIGH",
      costUSD: 1899.00
    },
    {
      assetType: "Security Token",
      sku: "YUBI-5C-NFC-DUAL",
      description: "YubiKey 5C NFC Enterprise Security Dual-Pack (Primary + Backup FIDO2)",
      priority: "CRITICAL",
      costUSD: 130.00
    }
  ];
} else {
  hardwareItems = [
    {
      assetType: "Business Workstation",
      sku: "LEN-T14S-G4",
      description: "Lenovo ThinkPad T14s Gen 4 (32GB RAM, 1TB SSD)",
      priority: "MEDIUM",
      costUSD: 1650.00
    },
    {
      assetType: "Standard Display",
      sku: "DELL-P2723DE",
      description: "Dell 27" QHD USB-C Hub Monitor",
      priority: "MEDIUM",
      costUSD: 420.00
    }
  ];
}

// Map each item with candidate metadata for individual Jira asset ticket generation
return hardwareItems.map((item, index) => ({
  json: {
    ...item,
    itemSequence: index + 1,
    totalItems: hardwareItems.length,
    recipientEmail: candidate.candidateEmail,
    recipientName: candidate.candidateName,
    department: candidate.assignedDepartment,
    clearanceLevel: candidate.securityClearance
  }
}));

